class Solution:
    def displayTable(self, orders):
        tables = {}
        foods = set()
        for _, t, f in orders:
            t = int(t)
            tables.setdefault(t, {})
            tables[t][f] = tables[t].get(f, 0) + 1
            foods.add(f)
        fl = sorted(foods)
        res = [["Table"] + fl]
        for t in sorted(tables):
            res.append([str(t)] + [str(tables[t].get(f, 0)) for f in fl])
        return res

