class Solution {
public:
    vector<vector<string>> displayTable(vector<vector<string>>& orders) {
        map<int, map<string, int>> tables;
        set<string> foods;
        for (auto& o : orders) {
            int t = stoi(o[1]);
            tables[t][o[2]]++;
            foods.insert(o[2]);
        }
        vector<vector<string>> res;
        vector<string> header{"Table"};
        for (auto& f : foods) header.push_back(f);
        res.push_back(header);
        for (auto& [t, cnt] : tables) {
            vector<string> row{to_string(t)};
            for (auto& f : foods) row.push_back(to_string(cnt.count(f) ? cnt[f] : 0));
            res.push_back(row);
        }
        return res;
    }
};

