class Solution {
    public List<List<String>> displayTable(List<List<String>> orders) {
        Map<Integer, Map<String, Integer>> tables = new TreeMap<>();
        TreeSet<String> foods = new TreeSet<>();
        for (List<String> o : orders) {
            int t = Integer.parseInt(o.get(1));
            tables.computeIfAbsent(t, k -> new HashMap<>()).merge(o.get(2), 1, Integer::sum);
            foods.add(o.get(2));
        }
        List<List<String>> res = new ArrayList<>();
        List<String> header = new ArrayList<>();
        header.add("Table");
        header.addAll(foods);
        res.add(header);
        for (Map.Entry<Integer, Map<String, Integer>> e : tables.entrySet()) {
            List<String> row = new ArrayList<>();
            row.add(String.valueOf(e.getKey()));
            Map<String, Integer> cnt = e.getValue();
            for (String f : foods) row.add(String.valueOf(cnt.getOrDefault(f, 0)));
            res.add(row);
        }
        return res;
    }
}

