var displayTable = function(orders) {
    const tables = new Map();
    const foods = new Set();
    for (const [, t, f] of orders) {
        if (!tables.has(+t)) tables.set(+t, new Map());
        const m = tables.get(+t);
        m.set(f, (m.get(f) || 0) + 1);
        foods.add(f);
    }
    const fl = [...foods].sort();
    const res = [["Table", ...fl]];
    for (const t of [...tables.keys()].sort((a, b) => a - b)) {
        const m = tables.get(t);
        res.push([String(t), ...fl.map(f => String(m.get(f) || 0))]);
    }
    return res;
};

