class Solution {
    public List<List<String>> displayTable(List<List<String>> orders) {
        Map<Long, Integer> cnt = new HashMap<>();
        Map<String, Integer> foodId = new HashMap<>();
        List<String> foodList = new ArrayList<>();
        Set<Integer> tables = new TreeSet<>();
        for (List<String> o : orders) {
            int t = Integer.parseInt(o.get(1));
            tables.add(t);
            foodId.computeIfAbsent(o.get(2), k -> { foodList.add(k); return foodId.size(); });
            cnt.merge((long)t * 100000L + foodId.get(o.get(2)), 1, Integer::sum);
        }
        Collections.sort(foodList);
        List<List<String>> res = new ArrayList<>();
        List<String> header = new ArrayList<>();
        header.add("Table");
        header.addAll(foodList);
        res.add(header);
        for (int t : tables) {
            List<String> row = new ArrayList<>();
            row.add(String.valueOf(t));
            for (String f : foodList)
                row.add(String.valueOf(cnt.getOrDefault((long)t * 100000L + foodId.get(f), 0)));
            res.add(row);
        }
        return res;
    }
}

